<div class="admin-heading"><div><p class="eyebrow">LES ARCHIVES</p><h1>Gérer les succès<span>.</span></h1><p class="admin-intro"><?= count($items) ?> succès, brouillons et archives inclus.</p></div><a class="primary-button" href="/admin/achievements/new">＋ Nouveau succès</a></div><section class="admin-panel neu-flat"><?php if (!$items): ?><div class="admin-empty"><?= icon('book') ?><h2>Aucun succès pour le moment.</h2><p>Les brouillons restent privés jusqu’à leur publication.</p></div><?php else: ?><form class="context-filters" data-context-filters><label>Publication<select name="publication"><option value="">Tous les états</option><option value="published">Publié</option><option value="draft">Brouillon</option><option value="archived">Archivé</option></select></label><label>Catégorie<select name="category"><option value="">Toutes</option><?php $filterCategories=[];foreach($items as $row)if($row['category'])$filterCategories[$row['category_id']]=$row['category'];foreach($filterCategories as $id=>$name): ?><option value="<?= e($id) ?>"><?= e($name) ?></option><?php endforeach; ?></select></label><button type="reset" class="secondary-button">Réinitialiser</button><p role="status" data-context-count><?= count($items) ?> résultats</p></form><div class="table-scroll"><table><thead><tr><th>Nom</th><th>Catégorie</th><th>État</th><th>Vérification</th><th>Actions</th></tr></thead><tbody><?php foreach ($items as $record): ?><tr data-filter-row data-publication="<?= $record['archived_at']?'archived':e($record['publication_status']) ?>" data-category="<?= e($record['category_id']??'') ?>"><td><a href="/admin/achievements/<?= $record['id'] ?>/edit"><?= e($record['name']) ?></a><small><?= e($record['slug']) ?></small></td><td><?= e($record['category'] ?? 'Non renseignée') ?></td><td><span class="admin-badge"><?= $record['archived_at'] ? 'Archivé' : ($record['publication_status']==='published'?'Publié':'Brouillon') ?></span></td><td><?= $record['verification_status']==='verified'?'Confirmé':'À confirmer' ?></td><td><a class="table-action" href="/admin/achievements/<?= $record['id'] ?>/edit">Modifier</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
